import React, { useRef } from 'react';
import { motion, useMotionValue, useSpring, useTransform } from 'framer-motion';
import { QrCode, Cpu } from '@phosphor-icons/react';

export const HangingIdCard: React.FC = () => {
  const cardRef = useRef<HTMLDivElement>(null);

  const x = useMotionValue(0);
  const y = useMotionValue(0);

  const mouseXSpring = useSpring(x, { stiffness: 200, damping: 20 });
  const mouseYSpring = useSpring(y, { stiffness: 200, damping: 20 });

  const rotateX = useTransform(mouseYSpring, [-0.5, 0.5], ['14deg', '-14deg']);
  const rotateY = useTransform(mouseXSpring, [-0.5, 0.5], ['-14deg', '14deg']);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!cardRef.current) return;
    const rect = cardRef.current.getBoundingClientRect();
    const width = rect.width;
    const height = rect.height;
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    x.set(mouseX / width - 0.5);
    y.set(mouseY / height - 0.5);
  };

  const handleMouseLeave = () => {
    x.set(0);
    y.set(0);
  };

  return (
    <div className="perspective-1000 flex flex-col items-center justify-center p-4">
      <div className="h-8 w-2 bg-gradient-to-b from-indigo-700 to-indigo-500 rounded-t-sm shadow-md" />
      <div className="h-2.5 w-5 rounded-sm bg-zinc-800 border border-white/20 mb-[-3px] z-20 shadow" />

      <motion.div
        ref={cardRef}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
        style={{ rotateX, rotateY, transformStyle: 'preserve-3d' }}
        className="relative w-52 h-76 rounded-3xl border border-white/20 bg-gradient-to-br from-zinc-900/90 via-zinc-950 to-black p-4 shadow-2xl backdrop-blur-xl flex flex-col justify-between text-white font-mono cursor-pointer select-none"
      >
        <div className="pointer-events-none absolute inset-0 rounded-3xl bg-gradient-to-tr from-transparent via-white/10 to-transparent opacity-60" />

        <div className="flex items-center justify-between z-10">
          <div className="flex items-center gap-1.5">
            <Cpu size={16} className="text-cyan-400" />
            <span className="text-[11px] font-bold tracking-wider">COOKI PASSPORT</span>
          </div>
          <span className="px-1.5 py-0.5 rounded-full bg-cyan-400/20 text-cyan-300 text-[8px] border border-cyan-400/30">
            PRO VIP
          </span>
        </div>

        <div className="flex flex-col items-center my-auto z-10">
          <div className="h-14 w-14 rounded-2xl bg-gradient-to-br from-indigo-500 to-violet-600 p-1 shadow-lg shadow-indigo-500/20 mb-2 flex items-center justify-center font-sans font-extrabold text-lg text-white">
            CK
          </div>
          <h4 className="font-bold text-xs text-white">Alex Vanguard</h4>
          <p className="text-[9px] text-zinc-400 mt-0.5">Staff Runtime Architect</p>
        </div>

        <div className="flex items-center justify-between border-t border-white/10 pt-2.5 z-10 text-[9px]">
          <div>
            <span className="text-zinc-500">ID TOKEN</span>
            <div className="font-bold text-zinc-300">#8942-CK</div>
          </div>
          <QrCode size={20} className="text-white" />
        </div>
      </motion.div>
    </div>
  );
};

import React, { useRef, useEffect } from 'react';

export const ParticleVortexTunnel: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;
    let isVisible = true;
    const stars: { x: number; y: number; z: number }[] = [];
    const count = 120;

    for (let i = 0; i < count; i++) {
      stars.push({
        x: (Math.random() - 0.5) * 400,
        y: (Math.random() - 0.5) * 400,
        z: Math.random() * 400,
      });
    }

    const render = () => {
      if (!isVisible) return;
      ctx.fillStyle = 'rgba(5, 5, 8, 0.25)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      const cx = canvas.width / 2;
      const cy = canvas.height / 2;

      for (let s of stars) {
        s.z -= 2.2;
        if (s.z <= 0) s.z = 400;

        const k = 200 / s.z;
        const px = s.x * k + cx;
        const py = s.y * k + cy;

        if (px >= 0 && px <= canvas.width && py >= 0 && py <= canvas.height) {
          const size = Math.max(0.8, (1 - s.z / 400) * 3);
          const alpha = 1 - s.z / 400;

          ctx.fillStyle = `rgba(129, 140, 248, ${alpha})`;
          ctx.beginPath();
          ctx.arc(px, py, size, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      animId = requestAnimationFrame(render);
    };

    animId = requestAnimationFrame(render);

    const observer = new IntersectionObserver(([entry]) => {
      const wasVisible = isVisible;
      isVisible = entry.isIntersecting;
      if (isVisible && !wasVisible) {
        animId = requestAnimationFrame(render);
      }
    }, { threshold: 0.05 });
    observer.observe(canvas);

    return () => {
      cancelAnimationFrame(animId);
      observer.disconnect();
    };
  }, []);

  return (
    <div className="relative w-full h-56 rounded-2xl overflow-hidden bg-black border border-white/10 flex items-center justify-center">
      <canvas ref={canvasRef} width={400} height={224} className="w-full h-full" />
      <span className="absolute z-10 bottom-3 px-3 py-1 rounded-full bg-zinc-900/80 text-[10px] font-mono text-zinc-400 border border-white/10">
        WARP TUNNEL VELOCITY
      </span>
    </div>
  );
};

import React, { useRef, useEffect } from 'react';

export const PlasmaGlobe: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;
    let t = 0;
    let isVisible = true;

    const render = () => {
      if (!isVisible) return;
      t += 0.03;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const cx = canvas.width / 2;
      const cy = canvas.height / 2;
      const radius = 50;

      const grad = ctx.createRadialGradient(cx, cy, 5, cx, cy, radius + 20);
      grad.addColorStop(0, '#a855f7');
      grad.addColorStop(0.4, '#6366f1');
      grad.addColorStop(0.8, '#06b6d4');
      grad.addColorStop(1, 'transparent');

      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(cx, cy, radius + 20, 0, Math.PI * 2);
      ctx.fill();

      for (let i = 0; i < 7; i++) {
        const angle = (i * Math.PI * 2) / 7 + Math.sin(t + i) * 0.3;
        const ex = cx + Math.cos(angle) * (radius + Math.sin(t * 2 + i) * 10);
        const ey = cy + Math.sin(angle) * (radius + Math.cos(t * 2 + i) * 10);

        ctx.strokeStyle = i % 2 === 0 ? '#38bdf8' : '#e879f9';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(cx, cy);
        ctx.quadraticCurveTo(
          cx + Math.cos(angle + 0.5) * 25,
          cy + Math.sin(angle + 0.5) * 25,
          ex,
          ey
        );
        ctx.stroke();
      }

      animId = requestAnimationFrame(render);
    };

    animId = requestAnimationFrame(render);

    const observer = new IntersectionObserver(([entry]) => {
      const wasVisible = isVisible;
      isVisible = entry.isIntersecting;
      if (isVisible && !wasVisible) {
        animId = requestAnimationFrame(render);
      }
    }, { threshold: 0.05 });
    observer.observe(canvas);

    return () => {
      cancelAnimationFrame(animId);
      observer.disconnect();
    };
  }, []);

  return (
    <div className="flex flex-col items-center justify-center p-3">
      <div className="relative rounded-full p-2 border border-white/20 bg-black/80 shadow-2xl">
        <canvas ref={canvasRef} width={160} height={160} className="rounded-full" />
      </div>
      <span className="mt-2 text-[10px] font-mono text-zinc-500 uppercase tracking-widest">
        Parametric Plasma Orb
      </span>
    </div>
  );
};

