  { type: 'add', oldNum: null, newNum: 15, text: "+  const fallback = window.matchMedia('(prefers-color-scheme: dark)');" },
  { type: 'add', oldNum: null, newNum: 16, text: "+  document.documentElement.classList.toggle('dark', fallback.matches);" },
