import React, { useRef } from 'react'
import { motion, useMotionValue, useSpring, useTransform } from 'framer-motion'
import { cn } from '@/lib/utils'

export interface MagneticButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  children?: React.ReactNode
  variant?: 'default' | 'glow' | 'minimal' | 'ghost'
  size?: 'sm' | 'md' | 'lg'
  distance?: number
  className?: string
}

export const MagneticButton: React.FC<MagneticButtonProps> = ({
  children = 'Magnetic Action',
  variant = 'default',
  size = 'md',
  distance = 60,
  className,
  ...props
}) => {
  const ref = useRef<HTMLButtonElement>(null)
  const x = useMotionValue(0)
  const y = useMotionValue(0)

  const springConfig = { damping: 15, stiffness: 150, mass: 0.1 }
  const springX = useSpring(x, springConfig)
  const springY = useSpring(y, springConfig)

  const handleMouseMove = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (!ref.current) return
    const rect = ref.current.getBoundingClientRect()
    const centerX = rect.left + rect.width / 2
    const centerY = rect.top + rect.height / 2
    const deltaX = (e.clientX - centerX) * 0.4
    const deltaY = (e.clientY - centerY) * 0.4
    x.set(deltaX)
    y.set(deltaY)
  }

  const handleMouseLeave = () => {
    x.set(0)
    y.set(0)
  }

  const sizeStyles = {
    sm: 'px-4 py-2 text-xs rounded-full gap-1.5',
    md: 'px-6 py-3 text-sm rounded-full gap-2',
    lg: 'px-8 py-4 text-base rounded-full gap-3 font-semibold',
  }

  const variantStyles = {
    default: 'bg-zinc-900 text-white border border-white/15 hover:border-white/30 dark:bg-zinc-100 dark:text-zinc-950 shadow-md',
    glow: 'bg-gradient-to-r from-cyan-500 to-blue-600 text-white shadow-lg shadow-cyan-500/25 border-0 hover:shadow-cyan-500/40',
    minimal: 'bg-white/10 text-zinc-200 border border-white/10 hover:bg-white/15 dark:bg-black/40',
    ghost: 'bg-transparent text-zinc-300 hover:text-white hover:bg-white/5 border border-transparent',
  }

  return (
    <motion.button
      ref={ref}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{ x: springX, y: springY }}
      whileTap={{ scale: 0.96 }}
      className={cn(
        'relative inline-flex items-center justify-center font-medium transition-colors select-none focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2',
        sizeStyles[size],
        variantStyles[variant],
        className
      )}
      {...(props as any)}
    >
      <motion.span
        style={{ x: useTransform(springX, (val) => val * 0.3), y: useTransform(springY, (val) => val * 0.3) }}
        className="flex items-center gap-2"
      >
        {children}
      </motion.span>
    </motion.button>
  )
}

import React, { useState } from 'react'
import { cn } from '@/lib/utils'

export interface RippleButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  children?: React.ReactNode
  className?: string
}

interface Ripple {
  x: number
  y: number
  size: number
  id: number
}

export const RippleButton: React.FC<RippleButtonProps> = ({
  children = 'Ripple Feedback',
  className,
  onClick,
  ...props
}) => {
  const [ripples, setRipples] = useState<Ripple[]>([])

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    const rect = e.currentTarget.getBoundingClientRect()
    const size = Math.max(rect.width, rect.height) * 2
    const x = e.clientX - rect.left - size / 2
    const y = e.clientY - rect.top - size / 2

    const newRipple: Ripple = { x, y, size, id: Date.now() }
    setRipples((prev) => [...prev, newRipple])

    setTimeout(() => {
      setRipples((prev) => prev.filter((r) => r.id !== newRipple.id))
    }, 600)

    onClick?.(e)
  }

  return (
    <button
      onClick={handleClick}
      className={cn(
        'relative inline-flex items-center justify-center overflow-hidden rounded-full border border-white/15 bg-zinc-900 px-6 py-3 font-mono text-xs font-semibold text-white shadow-lg transition-transform active:scale-95 focus:outline-none',
        className
      )}
      {...props}
    >
      <span className="relative z-10">{children}</span>
      {ripples.map((ripple) => (
        <span
          key={ripple.id}
          style={{
            top: ripple.y,
            left: ripple.x,
            width: ripple.size,
            height: ripple.size,
          }}
          className="pointer-events-none absolute rounded-full bg-cyan-400/30 animate-[ping_0.6s_ease-out_forwards]"
        />
      ))}
    </button>
  )
}

import React, { useState, useRef } from 'react'
import { motion, useMotionValue, useTransform } from 'framer-motion'
import { ArrowRight, Check, ShieldCheck } from '@phosphor-icons/react'
import { cn } from '@/lib/utils'

export interface SlideToConfirmProps {
  label?: string
  confirmedLabel?: string
  onConfirm?: () => void
  className?: string
}

export const SlideToConfirm: React.FC<SlideToConfirmProps> = ({
  label = 'Slide to Deploy Kernel',
  confirmedLabel = 'Kernel Deployed',
  onConfirm,
  className,
}) => {
  const [isConfirmed, setIsConfirmed] = useState(false)
  const trackRef = useRef<HTMLDivElement>(null)
  const x = useMotionValue(0)

  const handleDragEnd = () => {
    if (!trackRef.current) return
    const trackWidth = trackRef.current.offsetWidth
    const maxDrag = trackWidth - 56 // button width
    if (x.get() >= maxDrag * 0.85) {
      setIsConfirmed(true)
      onConfirm?.()
    } else {
      x.set(0)
    }
  }

  const handleReset = () => {
    setIsConfirmed(false)
    x.set(0)
  }

  return (
    <div className={cn('w-full max-w-sm', className)}>
      <div
        ref={trackRef}
        className={`relative flex h-14 w-full items-center justify-between rounded-full border p-1.5 transition-colors select-none ${
          isConfirmed
            ? 'border-emerald-500/40 bg-emerald-950/40'
            : 'border-white/15 bg-zinc-950 shadow-inner'
        }`}
      >
        {/* Track Label */}
        <div className="absolute inset-0 flex items-center justify-center font-mono text-xs font-semibold text-zinc-400 pointer-events-none">
          {isConfirmed ? (
            <span className="flex items-center gap-1.5 text-emerald-400">
              <Check size={16} weight="bold" />
              <span>{confirmedLabel}</span>
            </span>
          ) : (
            <span className="animate-pulse">{label}</span>
          )}
        </div>

        {/* Draggable Thumb */}
        {!isConfirmed ? (
          <motion.div
            drag="x"
            dragConstraints={{ left: 0, right: 260 }}
            dragElastic={0.05}
            onDragEnd={handleDragEnd}
            style={{ x }}
            className="relative z-10 flex h-11 w-11 cursor-grab active:cursor-grabbing items-center justify-center rounded-full bg-white text-zinc-950 shadow-xl transition-shadow hover:shadow-cyan-500/20"
          >
            <ArrowRight size={18} weight="bold" />
          </motion.div>
        ) : (
          <button
            onClick={handleReset}
            className="relative z-10 ml-auto flex h-11 w-11 items-center justify-center rounded-full bg-emerald-500 text-zinc-950 shadow-lg hover:scale-105 transition-transform"
            title="Click to reset"
          >
            <Check size={18} weight="bold" />
          </button>
        )}
      </div>
    </div>
  )
}

